{"path": "src/riskscore/recency.py", "content": """"How long since the product and the account were last active."""
import numpy as np
import pandas as pd


def sku_last_trade(fit_df):
    return fit_df.groupby("sku")["placed_at"].max()


def account_last_order(fit_df):
    known = fit_df.dropna(subset=["account_id"])
    return known.groupby("account_id")["placed_at"].max()


def staleness(last_seen, fit_end):
    return (fit_end - last_seen).dt.days.astype("float64")


def add(df, sku_stale, account_stale, portfolio_stale):
    out = df.copy()
    out["f_sku_days_since_trade"] = out["sku"].map(sku_stale).fillna(portfolio_stale)
    out["f_account_days_since_order"] = out["account_id"].map(account_stale).fillna(-1.0)
    return out
"}

{"path": "src/riskscore/cadence.py", "content": """"How regularly the product trades and the account orders."""
import numpy as np
import pandas as pd


def sku_trade_days(fit_df):
    days = fit_df["placed_at"].dt.normalize()
    return days.groupby(fit_df["sku"]).nunique().astype("float64")


def account_gap(fit_df):
    known = fit_df.dropna(subset=["account_id"])
    days = known["placed_at"].dt.normalize()

    def mean_gap(values):
        distinct = values.drop_duplicates().sort_values()
        if len(distinct) < 2:
            return np.nan
        return float(distinct.diff().dropna().dt.days.mean())

    gaps = days.groupby(known["account_id"]).apply(mean_gap).astype("float64")
    portfolio = float(gaps.mean())
    return gaps, portfolio


def add(df, trade_days, gaps, portfolio_gap):
    out = df.copy()
    out["f_sku_trade_days"] = out["sku"].map(trade_days).fillna(0.0)
    out["f_account_order_gap"] = out["account_id"].map(gaps).fillna(portfolio_gap)
    return out
"}

{"path": "src/riskscore/dispersion.py", "content": """"How much a sku's price has moved around its own usual level.

Lines priced unusually for their own sku are the ones that get sent back.
"""
import numpy as np
import pandas as pd


def price_dispersion(fit_df):
    def mad(prices):
        return float((prices - prices.mean()).abs().mean())

    return fit_df.groupby("sku")["unit_price"].apply(mad).astype("float64")


def add(df, dispersion):
    out = df.copy()
    portfolio = float(dispersion.mean())
    out["f_sku_price_dispersion"] = out["sku"].map(dispersion).fillna(portfolio)
    return out
"}

{"path": "src/riskscore/concentration.py", "content": """"How wide a price band a sku has traded in over the fit window."""
import numpy as np
import pandas as pd


def price_range(fit_df):
    grouped = fit_df.groupby("sku")["unit_price"]
    return (grouped.max() - grouped.min()).astype("float64")


def add(df, spread):
    out = df.copy()
    portfolio = float(spread.mean())
    out["f_sku_price_range"] = out["sku"].map(spread).fillna(portfolio)
    return out
"}

{"path": "src/riskscore/encoders.py", "content": """"Categorical rate encoding, fitted on the fit window.
"""
import numpy as np
import pandas as pd


class RateEncoder(object):

    def __init__(self, column, smoothing):
        self.column = column
        self.smoothing = float(smoothing)
        self.rates_ = None
        self.prior_ = None

    def fit(self, df, label):
        self.prior_ = float(df[label].mean())
        grouped = df.groupby(self.column)[label]
        self.rates_ = ((grouped.sum() + self.smoothing * self.prior_)
                       / (grouped.count() + self.smoothing)).astype("float64")
        return self

    def transform(self, df):
        return df[self.column].map(self.rates_).fillna(self.prior_).astype("float64")


def fit_all(fit_df, columns, smoothing, label):
    encoders = {}
    for column in columns:
        encoders[column] = RateEncoder(column, smoothing).fit(fit_df, label)
    return encoders


def apply_all(df, encoders):
    out = df.copy()
    for column, encoder in encoders.items():
        out["f_rate_%s" % column] = encoder.transform(out)
    return out
"}

